"""Cryptographic helpers: Ed25519 verification, SHA-256 ids and Merkle roots."""
from __future__ import annotations

import hashlib
import hmac
import json
import re

from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)


def canonical_message(sender: str, recipient: str, amount: int) -> bytes:
    """Deterministic byte representation of a transaction payload.

    The payload is serialized as compact JSON with sorted keys so the same
    (from, to, amount) triple always yields identical bytes on every client.
    """
    payload = {"amount": amount, "from": sender, "to": recipient}
    return json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def compute_tx_id(message: bytes) -> str:
    """SHA-256 hex digest of the canonical transaction message."""
    return sha256_hex(message)


def generate_private_key() -> str:
    """Generate a fresh Ed25519 private seed as 64 lowercase hex chars."""
    return Ed25519PrivateKey.generate().private_bytes(
        serialization.Encoding.Raw,
        serialization.PrivateFormat.Raw,
        serialization.NoEncryption(),
    ).hex()


def derive_public_key(private_key_hex: str) -> str | None:
    """Derive the 64-hex Ed25519 public key from a 64-hex private seed.

    Returns None for malformed hex or a wrong-length seed rather than raising,
    so callers can treat every malformed key uniformly as a 400.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return _public_hex(private_key)


def _public_hex(private_key: Ed25519PrivateKey) -> str:
    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


def sign_message(private_key_hex: str, message: bytes) -> str | None:
    """Sign ``message`` with an Ed25519 seed (64 hex chars); hex signature.

    Returns None for a malformed private key rather than raising.
    """
    try:
        seed = bytes.fromhex(private_key_hex)
    except ValueError:
        return None
    if len(seed) != 32:
        return None
    private_key = Ed25519PrivateKey.from_private_bytes(seed)
    return private_key.sign(message).hex()


def verify_signature(public_key_hex: str, message: bytes, signature_hex: str) -> bool:
    """Verify an Ed25519 signature (public key and signature are hex strings).

    Returns False for malformed hex or wrong key/signature lengths rather than
    raising, so callers can treat every verification failure uniformly.
    """
    try:
        public_bytes = bytes.fromhex(public_key_hex)
        signature_bytes = bytes.fromhex(signature_hex)
    except ValueError:
        return False
    if len(public_bytes) != 32 or len(signature_bytes) != 64:
        return False
    try:
        public_key = Ed25519PublicKey.from_public_bytes(public_bytes)
        public_key.verify(signature_bytes, message)
    except (InvalidSignature, ValueError):
        return False
    return True


# Merkle root of an empty transaction list; fixed so genesis blocks are identical.
EMPTY_MERKLE_ROOT = sha256_hex(b"")


def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


def verify_merkle_proof(
    tx_id: str,
    siblings: list[dict],
    merkle_root: str,
    block_hash: str,
    expected_block_hash: str,
) -> bool:
    """Verify a Merkle proof and bind it to a specific block hash.

    Re-hashes the leaf (``tx_id``) with the sibling path from leaf to root and
    compares the result with ``merkle_root``; ``block_hash`` must additionally
    equal ``expected_block_hash``. Every malformed input (non-64-char lowercase
    hex hash, illegal direction, non-list path, excessive depth) and every
    mismatch returns False rather than raising.
    """
    try:
        if not _is_hex64(tx_id):
            return False
        if not _is_hex64(merkle_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_block_hash):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        current = tx_id
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            if direction == "left":
                pair = sibling_hash + current
            elif direction == "right":
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))

        if not hmac.compare_digest(current, merkle_root):
            return False
        if not hmac.compare_digest(block_hash, expected_block_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False


# -- account state Merkle tree ----------------------------------------------


def account_state_leaf(
    account: str, balance: int, confirmed_transactions: list[str]
) -> str:
    """SHA-256 leaf of one account's confirmed state.

    The leaf is ``sha256(utf8(JSON))`` of the canonical compact JSON document
    ``{"account":a,"balance":b,"confirmed_transactions":T}`` serialized with
    ``sort_keys=True``, ``ensure_ascii=False`` and ``separators=(",",":")``.
    ``T`` keeps its original (on-chain) order; ``sort_keys`` only orders the
    three top-level keys.
    """
    document = {
        "account": account,
        "balance": balance,
        "confirmed_transactions": confirmed_transactions,
    }
    raw = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    return sha256_hex(raw)


def account_state_root(leaves: list[str]) -> str:
    """Merkle root of account-state leaves ordered by ascending account.

    Uses the same pairing rules as :func:`merkle_root` (hex-string pairs
    hashed ``sha256(left + right)``, a lone odd node paired with itself); an
    empty account set has the same root as an empty tx list.
    """
    return merkle_root(leaves)


def verify_account_proof(
    proof: object,
    expected_root: object,
    expected_height: object,
    expected_hash: object,
) -> bool:
    """Verify an account-state Merkle proof offline.

    Recomputes the account leaf from
    ``{account, balance, confirmed_transactions}``, walks the leaf-to-root
    ``siblings`` path, and requires the recomputed root to equal both the
    proof's ``state_root`` and ``expected_root``, while ``height`` /
    ``block_hash`` anchor the tree to the expected confirmed tip. Every
    malformed input — a non-64-char lowercase hex hash or anchor, an illegal
    direction, an illegal index, a malformed leaf/balance/transaction list, a
    path inconsistent with the index, excessive depth — returns False rather
    than raising.
    """
    try:
        if not isinstance(proof, dict):
            return False
        account = proof.get("account")
        balance = proof.get("balance")
        transactions = proof.get("confirmed_transactions")
        index = proof.get("index")
        state_root = proof.get("state_root")
        height = proof.get("height")
        block_hash = proof.get("block_hash")
        siblings = proof.get("siblings")

        if not isinstance(account, str) or not account:
            return False
        if isinstance(balance, bool) or not isinstance(balance, int) or balance < 0:
            return False
        if not isinstance(transactions, list):
            return False
        if any(not _is_hex64(tx_id) for tx_id in transactions):
            return False
        if isinstance(index, bool) or not isinstance(index, int) or index < 0:
            return False
        if not isinstance(height, bool) and isinstance(height, int):
            if height < 0:
                return False
        else:
            return False
        if not _is_hex64(state_root):
            return False
        if not _is_hex64(block_hash) or not _is_hex64(expected_hash):
            return False
        if not _is_hex64(expected_root):
            return False
        if not isinstance(siblings, list) or len(siblings) > MAX_MERKLE_DEPTH:
            return False

        # The leaf is always recomputed from the proof's own triple; a
        # client-supplied leaf value is never trusted.
        depth = len(siblings)
        # A depth-D path addresses one of 2**D leaf slots; a single-leaf tree
        # (D == 0) can only ever be index 0. An index outside that range is
        # illegal regardless of any hashes the caller supplies.
        if index >= (1 << depth):
            return False
        current = account_state_leaf(account, balance, transactions)
        position = index
        for item in siblings:
            if not isinstance(item, dict):
                return False
            direction = item.get("direction")
            sibling_hash = item.get("hash")
            if not _is_hex64(sibling_hash):
                return False
            # The odd-node promotion pairs the last (even-positioned) node
            # with a copy of itself, so a genuine self-pair always points at a
            # right sibling. A left sibling equal to the current node addresses
            # the phantom duplicate slot, which is never a real account.
            if direction == "left" and sibling_hash == current:
                return False
            # The path must agree with the index: at every level an even
            # position is the left child (sibling on its right) and an odd
            # position the right child.
            if direction == "left":
                if position % 2 == 0:
                    return False
                pair = sibling_hash + current
            elif direction == "right":
                if position % 2 == 1:
                    return False
                pair = current + sibling_hash
            else:
                return False
            current = sha256_hex(pair.encode("ascii"))
            position //= 2

        if not hmac.compare_digest(current, state_root):
            return False
        if not hmac.compare_digest(current, expected_root):
            return False
        if height != expected_height:
            return False
        if not hmac.compare_digest(block_hash, expected_hash):
            return False
        return True
    except (TypeError, ValueError):
        return False

"""Data models for transactions and blocks."""
from __future__ import annotations

import json
from dataclasses import dataclass

from . import crypto

# Block lifecycle states for the confirm/rollback state machine.
STATUS_PENDING = "pending"
STATUS_CONFIRMED = "confirmed"
BLOCK_STATUSES = (STATUS_PENDING, STATUS_CONFIRMED)


@dataclass
class Transaction:
    sender: str
    recipient: str
    amount: int
    signature: str

    @property
    def message(self) -> bytes:
        return crypto.canonical_message(self.sender, self.recipient, self.amount)

    @property
    def tx_id(self) -> str:
        return crypto.compute_tx_id(self.message)

    def to_dict(self) -> dict:
        """JSON-safe representation used both for storage and API output."""
        return {
            "from": self.sender,
            "to": self.recipient,
            "amount": self.amount,
            "signature": self.signature,
            "tx_id": self.tx_id,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Transaction":
        # The raw JSON value is validated BEFORE any use: no int()/str()
        # coercion, so a string, float or boolean amount can never masquerade
        # as the integer it converts to. bool is an int subclass and must be
        # rejected explicitly.
        amount = data["amount"]
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError("transaction amount must be an integer")
        return cls(
            sender=data["from"],
            recipient=data["to"],
            amount=amount,
            signature=data["signature"],
        )


def block_header_bytes(height: int, prev_hash: str, merkle: str) -> bytes:
    """Deterministic serialization of the fields covered by the block hash.

    No timestamp is included: a block with the same parent and the same ordered
    transactions must always hash identically.
    """
    header = {"height": height, "merkle_root": merkle, "prev_hash": prev_hash}
    return json.dumps(header, sort_keys=True, separators=(",", ":")).encode("utf-8")


def compute_block_hash(height: int, prev_hash: str, merkle: str) -> str:
    return crypto.sha256_hex(block_header_bytes(height, prev_hash, merkle))


@dataclass
class Block:
    height: int
    prev_hash: str
    merkle_root: str
    transactions: list[Transaction]
    block_hash: str
    status: str = STATUS_CONFIRMED

    @classmethod
    def create(
        cls,
        height: int,
        prev_hash: str,
        transactions: list[Transaction],
        status: str = STATUS_CONFIRMED,
    ) -> "Block":
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        ordered = sorted(transactions, key=lambda tx: tx.tx_id)
        merkle = crypto.merkle_root([tx.tx_id for tx in ordered])
        block_hash = compute_block_hash(height, prev_hash, merkle)
        return cls(
            height=height,
            prev_hash=prev_hash,
            merkle_root=merkle,
            transactions=ordered,
            block_hash=block_hash,
            status=status,
        )

    def to_dict(self) -> dict:
        return {
            "height": self.height,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "block_hash": self.block_hash,
            "status": self.status,
            "transactions": [tx.to_dict() for tx in self.transactions],
        }

    @classmethod
    def from_dict(cls, data: dict) -> "Block":
        # State files written before the status machine existed have no
        # "status" key; every block in such a file was final, so they load
        # as confirmed. This compatibility default never extends to numeric
        # coercion: the raw height must already be a non-boolean,
        # non-negative integer — a string, float or bool is rejected, never
        # converted.
        status = data.get("status", STATUS_CONFIRMED)
        if status not in BLOCK_STATUSES:
            raise ValueError(f"unknown block status: {status}")
        height = data["height"]
        if isinstance(height, bool) or not isinstance(height, int) or height < 0:
            raise ValueError("block height must be a non-negative integer")
        transactions = data["transactions"]
        if not isinstance(transactions, list):
            raise ValueError("block transactions must be a list")
        return cls(
            height=height,
            prev_hash=data["prev_hash"],
            merkle_root=data["merkle_root"],
            block_hash=data["block_hash"],
            transactions=[Transaction.from_dict(t) for t in transactions],
            status=status,
        )

    def to_summary(self) -> dict:
        """Response shape for GET /v1/blocks/{height}."""
        return {
            "height": self.height,
            "block_hash": self.block_hash,
            "prev_hash": self.prev_hash,
            "merkle_root": self.merkle_root,
            "status": self.status,
            "transaction_ids": [tx.tx_id for tx in self.transactions],
        }

        if entry is None:
            return 404, {"error": "account not found"}
        return 200, {
            "account": account,
            "balance": self.reported_balance(account),
            "confirmed_transactions": list(entry["transactions"]),
        }

# -- account state Merkle tree -------------------------------------------

def _state_tree(
    self, chain: list | None = None
) -> tuple[list[tuple[str, int, list[str]]], list[str], str]:
    """Build the confirmed account rows (ascending account), their leaves
    and the Merkle root, all from the confirmed chain under the current
    endowment. ``chain`` defaults to the whole canonical chain; a confirmed
    prefix replays historical state deterministically. Caller must hold the
    store lock.
    """
    if chain is None:
        chain = self.store.chain
    rows = self.store.account_state_rows(chain, self.initial_balance)
    leaves = [
        crypto.account_state_leaf(account, balance, transactions)
        for account, balance, transactions in rows
    ]
    return rows, leaves, crypto.account_state_root(leaves)

def get_state_root(self, height: object = None) -> tuple[int, dict]:
    """GET /v1/state/root and GET /v1/state/root/{height}.

    Without a height the tree is anchored to the highest block. A pending
    chain tip anchors nothing yet, so the endpoint returns 404 until the
    tip is confirmed.

    With a path height the state is replayed only from genesis through
    that block: the height must be an unsigned decimal without leading
    zeros (malformed heights are treated like any unknown path), the block
    must exist on the canonical chain and be confirmed — an unknown,
    non-canonical or pending height returns 404. The success body has
    exactly the same four fields as the unanchored endpoint.
    """
    with self.store.lock:
        if height is None:
            anchor = self.store.tip()
        else:
            # Strict unsigned decimal with no leading zeros, signs or
            # whitespace; every malformed value is an unknown path (404).
            height_int = _parse_decimal(height)
            if height_int is None:
                return 404, {"error": "block not found"}
            anchor = self.store.block_at(height_int)
            if anchor is None:
                return 404, {"error": "block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = self.store.chain if height is None else self.store.chain[: anchor.height + 1]
        rows, _leaves, root = self._state_tree(prefix)
        return 200, {
            "state_root": root,
            "height": anchor.height,
            "block_hash": anchor.block_hash,
            "account_count": len(rows),
        }

def get_account_proof(
    self, account: str, params: dict | None = None
) -> tuple[int, dict]:
    """GET /v1/accounts/{account}/proof — an inclusion proof in the
    account-state tree.

    Without ``height`` the proof is anchored to the highest (confirmed)
    block. With ``height=H`` the state is deterministically replayed from
    the canonical confirmed prefix through that block only: the value must
    be a plain non-negative decimal without leading zeros (a malformed or
    repeated query parameter is 400), and an unknown/non-canonical/pending
    anchor height is 404. Returns 404 while a pending tip anchors the
    default view, or for an account absent from the (historical) confirmed
    account set.
    """
    height_raw: object = None
    if params is not None:
        height_raw = params.get("height")
    anchor_height: int | None = None
    if height_raw is not None:
        anchor_height = _parse_decimal(height_raw)
        if anchor_height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    with self.store.lock:
        if anchor_height is None:
            anchor = self.store.tip()
        else:
            anchor = self.store.block_at(anchor_height)
            if anchor is None:
                return 404, {"error": "anchor block not found"}
        if anchor.status != STATUS_CONFIRMED:
            return 404, {"error": "chain tip is pending confirmation"}
        prefix = (
            self.store.chain
            if anchor_height is None
            else self.store.chain[: anchor.height + 1]
        )
        rows, leaves, root = self._state_tree(prefix)
        index = next(
            (i for i, (name, _b, _t) in enumerate(rows) if name == account),
            None,
        )
        if index is None:
            return 404, {"error": "account not found"}
        account_name, balance, transactions = rows[index]

"""Tests for offline light-client bundle verification (ledger.light_client).

Covers input/auth/expired/integrity/proof categorization, Ed25519 bundle
signing over the canonical unsigned document, full chain recomputation from
the pinned genesis, response/candidate-summary cross-checks, proof uniqueness
and the pending-tip ban, plus the offline ``ledger verify`` CLI (file and
stdin input, exit codes and single-line JSON output).

Run: python3 tests/light_client_test.py
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
import time
import unittest
from pathlib import Path

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

from ledger import crypto
from ledger.light_client import (
    ERR_AUTH,
    ERR_EXPIRED,
    ERR_INPUT,
    ERR_INTEGRITY,
    ERR_PROOF,
    bundle_signing_digest,
    canonical_bundle_bytes,
    verify_bundle,
)
from ledger.models import STATUS_PENDING, Block, Transaction
from ledger.store import LedgerStore

NOW = 1_000_000_000
FUTURE = NOW + 10_000
PAST = NOW - 1
BOB = "b" * 64


def pub_hex(key: Ed25519PrivateKey) -> str:
    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


class LightClientFixture(unittest.TestCase):
    def setUp(self) -> None:
        self.source_key = Ed25519PrivateKey.generate()
        self.source_pub = pub_hex(self.source_key)
        self.alice_key = Ed25519PrivateKey.generate()
        self.alice_pub = pub_hex(self.alice_key)

        self.genesis = LedgerStore.create_genesis()
        self.tx = Transaction(
            self.alice_pub, BOB, 100,
            self.alice_key.sign(
                crypto.canonical_message(self.alice_pub, BOB, 100)
            ).hex(),
        )
        self.block1 = Block.create(1, self.genesis.block_hash, [self.tx])
        self.tx2 = Transaction(
            self.alice_pub, BOB, 50,
            self.alice_key.sign(
                crypto.canonical_message(self.alice_pub, BOB, 50)
            ).hex(),
        )
        self.block_pending = Block.create(
            2, self.block1.block_hash, [self.tx2], status=STATUS_PENDING
        )
        self.chain = [self.genesis, self.block1]
        self.S = {
            "tip_hash": self.block1.block_hash,
            "height": 1,
            "length": 2,
            "status": "confirmed",
        }
        self.proof_doc = self._proof(self.block1, self.tx.tx_id)
        self.trust = {
            "genesis_hash": self.genesis.block_hash,
            "sources": {
                "node-a": {"public_key": self.source_pub, "expires_at": FUTURE}
            },
            "allowlist": {"node-b": FUTURE},
        }

    @staticmethod
    def _proof(block: Block, tx_id: str) -> dict:
        ids = [t.tx_id for t in block.transactions]
        index = ids.index(tx_id)
        return {
            "height": block.height,
            "tx_id": tx_id,
            "index": index,
            "merkle_root": block.merkle_root,
            "block_hash": block.block_hash,
            "siblings": crypto.merkle_proof(ids, index),
        }

    def bundle(
        self,
        *,
        blocks=None,
        proofs=None,
        source="node-a",
        expires_at=FUTURE,
        response=None,
        sign=True,
        wrap=False,
    ) -> dict:
        blocks = self.chain if blocks is None else blocks
        if proofs is None:
            proofs = [{"height": self.block1.height, "proof": self.proof_doc}]
        candidate = [b.to_dict() for b in blocks]
        if wrap:
            candidate = {
                "tip_hash": blocks[-1].block_hash,
                "height": blocks[-1].height,
                "length": len(blocks),
                "status": blocks[-1].status,
                "blocks": candidate,
            }
        bundle = {
            "source": source,
            "expires_at": expires_at,
            "response": dict(self.S) if response is None else response,
            "candidate": candidate,
            "proofs": proofs,
        }
        if sign:
            bundle["signature"] = self.source_key.sign(
                bundle_signing_digest(bundle)
            ).hex()
        return bundle

    def resign(self, bundle: dict) -> dict:
        bundle.pop("signature", None)
        bundle["signature"] = self.source_key.sign(
            bundle_signing_digest(bundle)
        ).hex()
        return bundle


class SuccessTests(LightClientFixture):
    def test_signed_happy_path(self) -> None:
        result = verify_bundle(self.bundle(), self.trust, now=NOW)
        self.assertEqual(
            result,
            {
                "ok": True,
                "source": "node-a",
                "S": self.S,
                "verified_tx_ids": [self.tx.tx_id],
            },
        )

    def test_allowlisted_unsigned(self) -> None:
        result = verify_bundle(
            self.bundle(source="node-b", sign=False), self.trust, now=NOW
        )
        self.assertTrue(result["ok"])
        self.assertEqual(result["source"], "node-b")
        self.assertEqual(result["verified_tx_ids"], [self.tx.tx_id])

    def test_no_proofs(self) -> None:
        result = verify_bundle(self.bundle(proofs=[]), self.trust, now=NOW)
        self.assertTrue(result["ok"])
        self.assertEqual(result["verified_tx_ids"], [])

    def test_response_may_be_superset(self) -> None:
        result = verify_bundle(
            self.bundle(response={**self.S, "transaction_ids": [self.tx.tx_id]}),
            self.trust,
            now=NOW,
        )
        self.assertTrue(result["ok"])

    def test_export_wrapped_candidate(self) -> None:
        result = verify_bundle(self.bundle(wrap=True), self.trust, now=NOW)
        self.assertTrue(result["ok"])
        self.assertEqual(result["S"], self.S)

    def test_canonical_bytes_stable_and_signature_covers_unsigned(self) -> None:
        bundle = self.bundle()
        unsigned = {k: v for k, v in bundle.items() if k != "signature"}
        expected = json.dumps(
            unsigned, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        self.assertEqual(canonical_bundle_bytes(bundle), expected)
        # Signature survives a key reorder of the outer bundle.
        reordered = {key: bundle[key] for key in reversed(list(bundle))}
        self.assertEqual(
            crypto.sha256_hex(canonical_bundle_bytes(reordered)),
            crypto.sha256_hex(expected),
        )


