def list_transactions(self, params: dict) -> tuple[int, dict]:
    """GET /v1/index/transactions — paginated confirmed-chain tx index.

    Pending-tip transactions are excluded. Filters (AND-combined):
    ``tx_id`` (64 lowercase hex), ``account`` (matches sender or
    recipient) and ``height``; ``limit`` (default 50, range 1-200) and
    ``cursor`` (default 0) paginate. Numeric filters must be plain
    decimals without leading zeros; any malformed value returns 400.
    Rows are ordered by (height, index, tx_id); ``index`` is the
    transaction's 0-based position inside its block, matching the Merkle
    proof index. A cursor beyond the filtered total returns 400, a cursor
    equal to it returns an empty page.
    """
    tx_id = params.get("tx_id")
    if tx_id is not None and not crypto.is_hex64(tx_id):
        return 400, {"error": "tx_id must be 64 lowercase hex characters"}
    account = params.get("account")
    if account is not None and (not isinstance(account, str) or not account):
        return 400, {"error": "account must be a non-empty string"}

    height = None
    if params.get("height") is not None:
        height = _parse_decimal(params["height"])
        if height is None:
            return 400, {"error": "height must be a non-negative decimal"}
    limit = self.INDEX_DEFAULT_LIMIT
    if params.get("limit") is not None:
        parsed = _parse_decimal(params["limit"])
        if parsed is None or not 1 <= parsed <= self.INDEX_MAX_LIMIT:
            return 400, {"error": "limit must be a decimal between 1 and 200"}
        limit = parsed
    cursor = 0
    if params.get("cursor") is not None:
        parsed = _parse_decimal(params["cursor"])
        if parsed is None:
            return 400, {"error": "cursor must be a non-negative decimal"}
        cursor = parsed

    with self.store.lock:
        rows: list[dict] = []
        for block in self.store.chain:
            if block.status != STATUS_CONFIRMED:
                continue
            if height is not None and block.height != height:
                continue
            for index, tx in enumerate(block.transactions):
                if tx_id is not None and tx.tx_id != tx_id:
                    continue
                if account is not None and account not in (tx.sender, tx.recipient):
                    continue
                rows.append(
                    {
                        "tx_id": tx.tx_id,
                        "height": block.height,
                        "block_hash": block.block_hash,
                        "index": index,
                        "from": tx.sender,
                        "to": tx.recipient,
                        "amount": tx.amount,
                    }
                )
    # Chain order is already (height, index) ascending; the tx_id
    # tiebreaker is implied because ids are unique within a block.
    total = len(rows)
    if cursor > total:
        return 400, {"error": "cursor is beyond the result set"}
    items = rows[cursor : cursor + limit]
    next_cursor = cursor + limit if cursor + limit < total else None
    return 200, {"items": items, "total": total, "next_cursor": next_cursor}

"""Command line interface: send, tx, mine, block, account, proof, state-root,
state-proof, confirm, rollback, status, candidates, chain, adopt, export,
index, sync, sync-range, sync-attested, sync-range-attested, syncs,
sync-history, chain-range,
audit, audit-export, trust
(add/rotate/revoke/export/allowlist-add/allowlist-remove) and offline
verify/audit-verify subcommands.

The CLI talks to a running ledger server over HTTP and prints each response as
a single line of JSON with exactly the same field names as the HTTP API.

Signing a transaction locally is supported through ``send --signing-key``;
the key may be 32 raw hex bytes or ``@/path/to/ed25519-key.pem``. An already
produced signature can be passed instead with ``--from/--signature``. The
``candidates`` subcommand takes the candidate fork's block array (or a
``{"blocks": [...]}`` object) as a single JSON argument.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from typing import Any

from . import crypto

DEFAULT_BASE_URL = os.environ.get("LEDGER_BASE_URL", "http://127.0.0.1:8080")


# -- HTTP helpers ------------------------------------------------------------


def _request(method: str, url: str, payload: dict | None) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload, sort_keys=True).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            body = {"error": exc.reason}
        return exc.code, body
    except (urllib.error.URLError, OSError) as exc:
        return 0, {"error": f"cannot reach ledger server: {exc}"}


def _emit(status: int, body: dict) -> int:
    print(json.dumps(body, sort_keys=True, ensure_ascii=False))
    # 2xx responses are success; anything else (incl. connection failure) is 1.
    return 0 if 200 <= status < 300 else 1


# -- signing key handling ----------------------------------------------------


def _load_signing_key(spec: str):
    """Load an Ed25519 private key from raw hex or an ``@file`` (hex or PEM)."""
    from cryptography.hazmat.primitives import serialization

    if spec.startswith("@"):
        with open(spec[1:], "rb") as fh:
            material = fh.read()
    else:
        material = spec.encode("ascii")
    stripped = material.strip()
    if stripped.startswith(b"-----BEGIN"):
        key = serialization.load_pem_private_key(stripped, password=None)
    else:
        raw = bytes.fromhex(stripped.decode("ascii"))
        if len(raw) != 32:
            raise ValueError("signing key must be 32 raw bytes (64 hex chars)")
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (
            Ed25519PrivateKey,
        )

        key = Ed25519PrivateKey.from_private_bytes(raw)
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    if not isinstance(key, Ed25519PrivateKey):
        raise ValueError("signing key is not an Ed25519 private key")
    return key


def _public_key_hex(key) -> str:
    from cryptography.hazmat.primitives import serialization

    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


